export default function PanelAdmina() { return "Panel administratora"; }

// App.js
async function ladujPanelAdmina() {
  const modul = await import("./PanelAdmina.js");
  console.log(modul.default()); // "Panel administratora"
}
ladujPanelAdmina();

// Mechanizm React.lazy() opiera sie DOKLADNIE na tym wzorcu - wewnatrz
