import { Guzik, Karta } from "./index.js";
console.log(Guzik(), Karta()); // -> guzik karta

// Licznik.js
export default class Licznik {
  n = 0;
  inc(krok) {
    this.n += krok;
    return this;
  }
}
export const krokDomyslny = 1;

// App.js
import Licznik, { krokDomyslny } from "./Licznik.js";
const l = new Licznik();
l.inc(krokDomyslny).inc(krokDomyslny).inc(krokDomyslny);
console.log(l.n); // -> 3

// Formularz.js
export default class Formularz {
  pola = {};
  ustaw(klucz, wartosc) {
    this.pola[klucz] = wartosc;
    return this;
  }
}
