// Walidatory.js
export function niepusty(s) {
  return s.length > 0;
}
export function liczba(s) {
  return !isNaN(Number(s));
}

// App.js
import * as Walidatory from "./Walidatory.js";
console.log(Walidatory.niepusty("test"), Walidatory.liczba("42")); // -> true true

// StatusKomponentu.js
export default { gotowy: false };

// App.js
async function ustawGotowy() {
  const modul = await import("./StatusKomponentu.js");
  modul.default.gotowy = true;
}
async function sprawdzGotowy() {
  const modul = await import("./StatusKomponentu.js");
  return modul.default.gotowy;
}
async function main() {
  await ustawGotowy();
  console.log(await sprawdzGotowy()); // -> true
}
main();

