// WykresKolowy.js
export default function WykresKolowy(dane) {
  return "wykres: " + dane.length + " punktow";
}

// App.js
async function renderujWykres(dane, pokazac) {
  if (!pokazac) return "ukryty";
  const { default: WykresKolowy } = await import("./WykresKolowy.js");
  return WykresKolowy(dane);
}
renderujWykres([1, 2, 3], true).then(console.log);  // -> "wykres: 3 punktow"
renderujWykres([1, 2, 3], false).then(console.log); // -> "ukryty"

// Tabela.js
export default class Tabela {
  wiersze = [];
  dodajWiersz(w) {
    this.wiersze.push(w);
    return this;
  }
  liczbaWierszy() {
    return this.wiersze.length;
  }
}

// App.js
import Tabela from "./Tabela.js";
const t = new Tabela();
t.dodajWiersz("a").dodajWiersz("b").dodajWiersz("c");
console.log(t.liczbaWierszy()); // -> 3

// Formatery.js
export function waluta(n) {
  return n.toFixed(2) + " zl";
}
export function procent(n) {
  return (n * 100).toFixed(0) + "%";
}

// App.js
import * as Formatery from "./Formatery.js";
console.log(Formatery.waluta(12.5), Formatery.procent(0.25));
// -> "12.50 zl" "25%"

// GeneratorRaportu.js
export default function generujRaport() {
  return "raport gotowy";
}

// App.js
async function pobierzRaport(dostepny) {
  if (!dostepny) return "brak danych";
  const modul = await import("./GeneratorRaportu.js");
  return modul.default();
}
pobierzRaport(false).then(console.log); // -> "brak danych"
pobierzRaport(true).then(console.log);  // -> "raport gotowy"

// Awatar.js
export default function Awatar({ imie }) {
  return imie.charAt(0).toUpperCase();
}

// App.js
import Awatar from "./Awatar.js";
console.log(Awatar({ imie: "kasia" }), Awatar({ imie: "tomek" }));
// -> "K" "T"

// Zegar.js
export function formatujCzas(godz, min) {
  return String(godz).padStart(2, "0") + ":" + String(min).padStart(2, "0");
}

// App.js
import { formatujCzas } from "./Zegar.js";
console.log(formatujCzas(9, 5)); // -> "09:05"

// Odznaka.js
export default function Odznaka(status) {
  return status === "nowy" ? "[nowy]" : "";
}

// App.js
import Odznaka from "./Odznaka.js";
console.log(Odznaka("nowy"), Odznaka("stary")); // -> "[nowy]" ""

// Menu.js
export function renderujPozycje(nazwy) {
  return nazwy.map((n) => "- " + n);
}

// App.js
import { renderujPozycje } from "./Menu.js";
console.log(renderujPozycje(["Start", "Kontakt"]));
// -> ["- Start", "- Kontakt"]

